# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::FinancialSnapshot, :two_tenant_seed do
  it "emits snapshot change signals that carry identifiers and the company id but no money values" do
    invoice = fork_and_leaf.invoices.order(:id).first
    expect(invoice).to be_present

    before_snapshot = described_class.take(company_id: fork_and_leaf.id)
    invoice.update_column(:amount, BigDecimal("987654.32"))
    after_snapshot = described_class.take(company_id: fork_and_leaf.id)
    differences = described_class.compare(before_snapshot, after_snapshot)
    amount_difference = differences.find { |difference| difference.kind == :invoice && difference.field == :amount }
    expect(amount_difference).to be_present

    # "Each difference is emitted as a signal carrying `company_id` through `Rails.event.notify`, following `app/events/users/signed_in.rb`."
    # The event history spans every workspace and docs/ai/events.md says payloads hold identifiers and enums only,
    # so the old and new money values must stay out of the stored signal.
    event = assert_event_reported("Timekeeping::FinancialSnapshotChanged") do
      described_class.report([amount_difference])
    end
    data = event[:payload].to_h[:data]

    expect(data.keys).to contain_exactly(:company_id, :kind, :record_id, :field)
    expect(data[:company_id]).to eq(fork_and_leaf.id)
    expect(data[:record_id]).to eq(invoice.id)
    expect(JSON.generate(event[:payload].to_h)).not_to include("987654")
  end
end

RSpec.describe Timekeeping::FinancialSnapshot, :two_tenant_seed do
  it "refuses to compare snapshots of two different companies" do
    fork_and_leaf_snapshot = described_class.take(company_id: fork_and_leaf.id)
    copper_kettle_snapshot = described_class.take(company_id: copper_kettle.id)

    # "Every check is keyed by `company_id`. No report or result mixes companies."
    expect {
      described_class.compare(fork_and_leaf_snapshot, copper_kettle_snapshot)
    }.to raise_error(ArgumentError)
  end
end

RSpec.describe Timekeeping::FinancialSnapshot, :two_tenant_seed do
  it "takes a snapshot that holds no invoice, line item or invoice tax of another company" do
    other_invoice = copper_kettle.invoices.order(:id).first
    expect(other_invoice).to be_present
    other_tax = create(:invoice_tax, invoice: other_invoice)

    snapshot = described_class.take(company_id: fork_and_leaf.id)

    # "A snapshot of one company never contains another company's invoices."
    expect(snapshot[:company_id]).to eq(fork_and_leaf.id)
    expect(snapshot[:values]).not_to be_empty
    ids_by_kind = snapshot[:values].keys.group_by(&:first).transform_values { |keys| keys.map { |key| key[1] }.uniq }

    own_invoice_ids = Invoice.where(company_id: fork_and_leaf.id).pluck(:id)
    own_line_item_ids = InvoiceLineItem.where(invoice_id: own_invoice_ids).pluck(:id)
    own_tax_ids = InvoiceTax.where(invoice_id: own_invoice_ids).pluck(:id)

    expect(ids_by_kind.fetch(:invoice, []) - own_invoice_ids).to be_empty
    expect(ids_by_kind.fetch(:pdf_total, []) - own_invoice_ids).to be_empty
    expect(ids_by_kind.fetch(:line_item, []) - own_line_item_ids).to be_empty
    expect(ids_by_kind.fetch(:invoice_tax, []) - own_tax_ids).to be_empty
    expect(ids_by_kind.fetch(:pdf_invoice_tax, []) - own_tax_ids).to be_empty
    expect(ids_by_kind.fetch(:invoice_tax, [])).not_to include(other_tax.id)
    expect(ids_by_kind.fetch(:invoice, [])).not_to include(other_invoice.id)
  end
end
